// สร้างรายการคำสั่งโดยเติม choices ของ pill จากตาราง devices ตอนรัน
// แทนที่จะเขียนชื่อ Pill ตายตัวไว้ในไฟล์ — เพิ่ม Pill ใหม่แล้วรัน workflow นี้ซ้ำ
// รายการก็อัปเดตเอง ไม่ต้องมาแก้ JSON
// (Discord จำกัด choices ไม่เกิน 25 ตัวต่อ option ตอนนี้มี 2 ตัว ยังห่างมาก)
const pills = $input.all()
  .map(i => i.json.device_name)
  .filter(Boolean)
  .slice(0, 25);
if (!pills.length) throw new Error('ไม่พบ Pill ในตาราง devices — รัน Sync Devices ก่อน');

const commands = [{"name": "ferment_start", "description": "เริ่ม batch การหมักใหม่ (Controller จะดึงจากที่ Pill จับคู่ไว้ใน RAPT อัตโนมัติ)", "options": [{"name": "pill", "description": "ชื่อ Pill (เช่น Pill01)", "type": 3, "required": true}, {"name": "beer", "description": "ชื่อเบียร์", "type": 3, "required": true}, {"name": "date", "description": "วันเวลาเริ่มหมัก เช่น 12/8/2026 00:00", "type": 3, "required": true}, {"name": "recipe", "description": "ชื่อ recipe ใน Brewfather (optional, เอาไว้ดึง OG/FG/ยีสต์แนะนำ)", "type": 3, "required": false, "autocomplete": true}]}, {"name": "ferment_stop", "description": "หยุด batch การหมักที่ active อยู่", "options": [{"name": "pill", "description": "ชื่อ Pill (เช่น Pill01)", "type": 3, "required": true}]}, {"name": "ferment_status", "description": "เช็คสถานะการหมักล่าสุดของ batch (เฟส, gravity, อุณหภูมิ, เหตุผลจาก AI)", "options": [{"name": "pill", "description": "ชื่อ Pill (เช่น Pill01)", "type": 3, "required": true}]}, {"name": "ferment_set_temp", "description": "ปรับ target temperature ของ Controller ที่จับคู่กับ Pill นี้ (สั่งตรงผ่าน RAPT API)", "options": [{"name": "pill", "description": "ชื่อ Pill (เช่น Pill01)", "type": 3, "required": true}, {"name": "target", "description": "target temperature ใหม่ (°C)", "type": 10, "required": true}, {"name": "remark", "description": "เหตุผลที่ปรับ เช่น adjust, d rest, cold crash", "type": 3, "required": false}]}, {"name": "ferment_recipes", "description": "แสดงรายชื่อ recipe ที่มีใน Brewfather cache (เอาไว้ดูชื่อก่อนพิมพ์ /ferment_start)", "options": [{"name": "search", "description": "คำค้นหา (optional, กรองเฉพาะชื่อที่ match)", "type": 3, "required": false}]}, {"name": "ferment_band", "description": "ตั้งช่วงอุณหภูมิของเบียร์ (Pill) ที่ยอมรับได้ — Temp Guard จะเตือนเมื่อหลุดช่วงนี้", "options": [{"name": "pill", "description": "ชื่อ Pill (เช่น Pill01)", "type": 3, "required": true}, {"name": "low", "description": "อุณหภูมิเบียร์ต่ำสุดที่ยอมรับได้ เช่น 18.0", "type": 10, "required": false}, {"name": "high", "description": "อุณหภูมิเบียร์สูงสุดที่ยอมรับได้ เช่น 18.5", "type": 10, "required": false}, {"name": "clear", "description": "true = ล้างช่วงที่ตั้งไว้ กลับไปใช้แค่ช่วงที่ยีสต์รองรับ", "type": 5, "required": false}]}, {"name": "ferment_event", "description": "บันทึกเหตุการณ์ที่ทำจริงกับ batch (dry hop, ลงยีสต์, ถ่ายถัง) — ต่างจากแผนในสูตร", "options": [{"name": "pill", "description": "ชื่อ Pill (เช่น Pill01)", "type": 3, "required": true}, {"name": "type", "description": "ชนิดเหตุการณ์", "type": 3, "required": true, "choices": [{"name": "🌿 Dry hop", "value": "dry_hop"}, {"name": "🧫 ลงยีสต์", "value": "pitch"}, {"name": "🔄 ถ่ายถัง", "value": "transfer"}, {"name": "🧪 เก็บตัวอย่าง", "value": "sample"}, {"name": "📝 อื่นๆ", "value": "other"}, {"name": "↩️ ยกเลิกรายการล่าสุด", "value": "undo"}]}, {"name": "date", "description": "วันเวลาที่เกิดจริง d/m/yyyy HH:mm (ไม่ใส่ = ตอนนี้)", "type": 3, "required": false}, {"name": "note", "description": "รายละเอียด เช่น รอบ 1 Citra+Amarillo", "type": 3, "required": false}]}];

// ทุกคำสั่งที่รับ pill เปลี่ยนจากพิมพ์เองเป็นเลือกจากรายการ
commands.forEach(cmd => {
  (cmd.options || []).forEach(opt => {
    if (opt.name === 'pill') {
      opt.choices = pills.map(p => ({ name: p, value: p }));
      opt.description = 'เลือก Pill';
    }
  });
});
return [{ json: { body: JSON.stringify(commands) } }];
